-- ==============================================================================
-- 📐 SUBMAPS (Modo Redimensionamento Interativo)
-- ==============================================================================
hl.define_submap("resize", function()
    local function exit_resize()
        hl.dispatch(hl.dsp.exec_cmd([[notify-send -e -u low -h string:x-canonical-private-synchronous:submap_notif -a "Hyprland" "✓ Modo Normal" "Tamanho confirmado."]]))
        hl.dispatch(hl.dsp.submap("reset"))
    end
    
    hl.bind("right", hl.dsp.window.resize({ x = 30, y = 0, relative = true }), { repeating = true, description = "resize right (+30)" })
    hl.bind("left", hl.dsp.window.resize({ x = -30, y = 0, relative = true }), { repeating = true, description = "resize left (-30)" })
    hl.bind("up", hl.dsp.window.resize({ x = 0, y = -30, relative = true }), { repeating = true, description = "resize up (-30)" })
    hl.bind("down", hl.dsp.window.resize({ x = 0, y = 30, relative = true }), { repeating = true, description = "resize down (+30)" })
    
    hl.bind("l", hl.dsp.window.resize({ x = 30, y = 0, relative = true }), { repeating = true, description = "resize right (+30)" })
    hl.bind("h", hl.dsp.window.resize({ x = -30, y = 0, relative = true }), { repeating = true, description = "resize left (-30)" })
    hl.bind("k", hl.dsp.window.resize({ x = 0, y = -30, relative = true }), { repeating = true, description = "resize up (-30)" })
    hl.bind("j", hl.dsp.window.resize({ x = 0, y = 30, relative = true }), { repeating = true, description = "resize down (+30)" })
    
    hl.bind("Escape", exit_resize, { description = "Concluir redimensionamento" })
    hl.bind("Return", exit_resize, { description = "Concluir redimensionamento" })
    hl.bind("SUPER + R", exit_resize, { description = "Concluir redimensionamento" })
end)
